class Solution {
  public int firstArrivalsEvenKeyCensus(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>seen=new HashSet<>();for(int x:a)if(seen.add(x))out.add(x);}
    int answer=0;for(int x:out)if(x%2==0)answer++;return answer;
  }
}
